/* one decision function: success only for an explicit grant */
int authorize(const struct subject *s, enum op op, const struct resource *r)
{
    const struct grant *g = grants_lookup(s, op, r);
    if (g == NULL) { audit_deny(s, op); errno = EACCES; return -1; }  /* no grant */
    return 0;                                                         /* allowed */
}
